//! Geometry primitives for the Clipper2 re-implementation.
//!
//! Mirrors the parts of Clipper2Lib's core geometry types that the boolean
//! module needs: 64-bit integer points, path types, signed area, and
//! segment helpers. All orientation predicates use 128-bit integer
//! arithmetic so they are exact for `i64` coordinates.

/// A point with 64-bit integer coordinates (Clipper2 `Point64`).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Point64 {
    pub x: i64,
    pub y: i64,
}

impl Point64 {
    pub fn new(x: i64, y: i64) -> Self {
        Point64 { x, y }
    }
}

/// A single polygon contour (Clipper2 `Path64`).
pub type Path64 = Vec<Point64>;
/// A set of polygon contours (Clipper2 `Paths64`).
pub type Paths64 = Vec<Path64>;

/// Winding rule used when filling open/self-overlapping geometry.
/// The boolean module only needs to handle simple polygons, where all
/// rules agree, but the enum is part of the shared API contract.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum FillRule {
    EvenOdd,
    NonZero,
    Positive,
    Negative,
}

/// Signed area of a polygon; positive for counter-clockwise winding
/// (standard Cartesian y-up), matching Clipper2's `Area()`.
///
/// Uses the shoelace formula. The sum of cross products of `i64`
/// coordinates is accumulated in `i128`, so the result is exact
/// regardless of coordinate magnitude; it is returned as `f64` to
/// match Clipper2's API.
pub fn area(path: &Path64) -> f64 {
    let n = path.len();
    if n < 3 {
        return 0.0;
    }
    let mut acc: i128 = 0;
    for i in 0..n {
        let p = path[i];
        let q = path[(i + 1) % n];
        acc += p.x as i128 * q.y as i128 - q.x as i128 * p.y as i128;
    }
    acc as f64 / 2.0
}

/// `true` iff the polygon winds counter-clockwise (`area(path) > 0`).
pub fn is_positive(path: &Path64) -> bool {
    area(path) > 0.0
}

/// 128-bit cross product `(a - o) x (b - o)`; sign is positive iff
/// `o -> a -> b` is a left turn (counter-clockwise, y-up).
pub fn cross(o: Point64, a: Point64, b: Point64) -> i128 {
    (a.x as i128 - o.x as i128) * (b.y as i128 - o.y as i128)
        - (a.y as i128 - o.y as i128) * (b.x as i128 - o.x as i128)
}

/// `true` iff `p` lies on the closed segment `a`-`b` (exact, integer test).
pub fn point_on_segment(p: Point64, a: Point64, b: Point64) -> bool {
    if cross(a, b, p) != 0 {
        return false;
    }
    // Collinear: check p is within the bounding box of the segment.
    p.x >= a.x.min(b.x)
        && p.x <= a.x.max(b.x)
        && p.y >= a.y.min(b.y)
        && p.y <= a.y.max(b.y)
}

/// A segment intersection reported in floating point.
///
/// `t` (resp. `u`) is the parametric position along the first (resp.
/// second) segment: `point = p1 + t * (p2 - p1)`, with `t, u` in `[0, 1]`.
#[derive(Clone, Copy, PartialEq, Debug)]
pub struct SegIntersection {
    pub point: (f64, f64),
    pub t: f64,
    pub u: f64,
}

/// Computes the proper intersection of segments `p1`-`p2` and `p3`-`p4`.
///
/// Returns `Some` when the segments are not parallel and the intersection
/// point lies on both segments (inclusive of endpoints). Collinear and
/// parallel segments return `None` (overlapping-collinear cases are a
/// degeneracy the boolean module skips rather than reports).
pub fn segment_intersection(
    p1: Point64,
    p2: Point64,
    p3: Point64,
    p4: Point64,
) -> Option<SegIntersection> {
    let d1x = (p2.x - p1.x) as f64;
    let d1y = (p2.y - p1.y) as f64;
    let d2x = (p4.x - p3.x) as f64;
    let d2y = (p4.y - p3.y) as f64;
    let denom = d1x * d2y - d1y * d2x;
    // Parallel (or a zero-length segment): no unique intersection.
    if denom.abs() < 1e-12 {
        return None;
    }
    let ex = (p3.x - p1.x) as f64;
    let ey = (p3.y - p1.y) as f64;
    let t = (ex * d2y - ey * d2x) / denom;
    let u = (ex * d1y - ey * d1x) / denom;
    const EPS: f64 = 1e-9;
    if t < -EPS || t > 1.0 + EPS || u < -EPS || u > 1.0 + EPS {
        return None;
    }
    let t = t.clamp(0.0, 1.0);
    let u = u.clamp(0.0, 1.0);
    Some(SegIntersection {
        point: (p1.x as f64 + t * d1x, p1.y as f64 + t * d1y),
        t,
        u,
    })
}

/// Rounds a floating-point point to the integer grid, matching
/// Clipper2's round-to-nearest grid snapping of intersection vertices.
pub fn round_point(pt: (f64, f64)) -> Point64 {
    Point64::new(pt.0.round() as i64, pt.1.round() as i64)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn path(pts: &[(i64, i64)]) -> Path64 {
        pts.iter().map(|&(x, y)| Point64::new(x, y)).collect()
    }

    #[test]
    fn area_ccw_is_positive() {
        // Unit square wound CCW (y-up).
        let p = path(&[(0, 0), (1, 0), (1, 1), (0, 1)]);
        assert_eq!(area(&p), 1.0);
        assert!(is_positive(&p));
        // Reversed (CW) is negative.
        let mut q = p.clone();
        q.reverse();
        assert_eq!(area(&q), -1.0);
        assert!(!is_positive(&q));
    }

    #[test]
    fn area_of_degenerate_paths_is_zero() {
        assert_eq!(area(&path(&[])), 0.0);
        assert_eq!(area(&path(&[(0, 0)])), 0.0);
        assert_eq!(area(&path(&[(0, 0), (5, 5)])), 0.0);
    }

    #[test]
    fn area_is_exact_for_large_coordinates() {
        // Coordinates near i64 limits would overflow i64-only shoelace math.
        let big: i64 = 4_000_000_000;
        let p = path(&[(-big, -big), (big, -big), (big, big), (-big, big)]);
        assert_eq!(area(&p), 4.0 * (big as f64) * (big as f64));
    }

    #[test]
    fn cross_sign() {
        let o = Point64::new(0, 0);
        let a = Point64::new(1, 0);
        let b = Point64::new(0, 1);
        assert!(cross(o, a, b) > 0); // left turn
        assert!(cross(o, b, a) < 0); // right turn
        assert_eq!(cross(o, a, Point64::new(2, 0)), 0); // collinear
    }

    #[test]
    fn point_on_segment_cases() {
        let a = Point64::new(0, 0);
        let b = Point64::new(10, 0);
        assert!(point_on_segment(Point64::new(5, 0), a, b));
        assert!(point_on_segment(a, a, b)); // endpoints count
        assert!(point_on_segment(b, a, b));
        assert!(!point_on_segment(Point64::new(11, 0), a, b));
        assert!(!point_on_segment(Point64::new(5, 1), a, b));
    }

    #[test]
    fn segment_intersection_crossing() {
        let r = segment_intersection(
            Point64::new(100, 0),
            Point64::new(100, 100),
            Point64::new(50, 50),
            Point64::new(150, 50),
        )
        .expect("segments cross");
        assert_eq!(r.point, (100.0, 50.0));
        assert_eq!(r.t, 0.5);
        assert_eq!(r.u, 0.5);
        assert_eq!(round_point(r.point), Point64::new(100, 50));
    }

    #[test]
    fn segment_intersection_no_hit() {
        // Parallel segments.
        assert!(segment_intersection(
            Point64::new(0, 0),
            Point64::new(10, 0),
            Point64::new(0, 1),
            Point64::new(10, 1),
        )
        .is_none());
        // Lines would cross outside the segments.
        assert!(segment_intersection(
            Point64::new(0, 0),
            Point64::new(1, 0),
            Point64::new(5, -1),
            Point64::new(5, 1),
        )
        .is_none());
        // Zero-length segment.
        assert!(segment_intersection(
            Point64::new(0, 0),
            Point64::new(0, 0),
            Point64::new(-1, 0),
            Point64::new(1, 0),
        )
        .is_none());
    }
}
